// Parse the AI agent's bug-analysis output, validate it, normalize fields,
// and compute a deterministic auto-fix eligibility score. No extra API calls.
const cfg = $('Prepare Bug Report Data').first().json;
const agentOutput = $input.first().json;

let raw = agentOutput.output || agentOutput.text || agentOutput.response || '{}';
raw = String(raw).replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse AI bug-analysis output as JSON: ' + e.message);
}

const COMPLEXITY_RANK = { low: 1, medium: 2, high: 3 };

function normalizeComplexity(value) {
  const c = String(value || '').toLowerCase().trim();
  return COMPLEXITY_RANK.hasOwnProperty(c) ? c : 'medium';
}

function normalizeConfidence(value) {
  const n = parseFloat(value);
  if (isNaN(n)) return 0;
  return Math.min(1, Math.max(0, n));
}

const affectedFiles = Array.isArray(parsed.affectedFiles) ? parsed.affectedFiles.filter(Boolean) : [];
const riskFlags = Array.isArray(parsed.riskFlags) ? parsed.riskFlags.map(f => String(f).toLowerCase()) : [];

const HIGH_RISK_KEYWORDS = ['auth', 'payment', 'billing', 'migration', 'schema', 'secret', 'encryption', 'permission'];
const touchesHighRiskArea = riskFlags.some(f => HIGH_RISK_KEYWORDS.some(k => f.includes(k)));

const rootCause = parsed.rootCause || parsed.cause || 'Root cause not clearly identified.';
const fixApproach = parsed.fixApproach || parsed.approach || 'No fix approach provided.';
const fixComplexity = normalizeComplexity(parsed.fixComplexity || parsed.complexity);
const confidence = normalizeConfidence(parsed.confidence);
const testPlan = parsed.testPlan || parsed.tests || 'No test plan provided.';

// Deterministic eligibility gate: high confidence, low/medium complexity,
// no high-risk area touched, and at least one affected file identified.
const autoFixEligible =
  confidence >= cfg.autoFixConfidenceThreshold &&
  fixComplexity !== 'high' &&
  !touchesHighRiskArea &&
  affectedFiles.length > 0;

const fixId = 'FIX-' + cfg.bugId + '-' + Date.now();

return [{
  json: {
    ...cfg,
    fixId,
    rootCause,
    fixApproach,
    fixComplexity,
    confidence,
    affectedFiles,
    riskFlags,
    touchesHighRiskArea,
    testPlan,
    autoFixEligible
  }
}];

