// Combine the validated bug analysis with the review context (auto-approved because
// confidence was high, or acknowledged by a developer via the Wait node above) into
// a Cursor background-agent task payload.
const analysis = $('Analyze Auto-Fix Eligibility').first().json;
const resumeInput = $input.first().json;

let reviewedBy = 'auto (confidence ' + analysis.confidence + ' >= threshold ' + analysis.autoFixConfidenceThreshold + ')';
let reviewerNotes = '';

if (!analysis.autoFixEligible) {
  const body = resumeInput.body || resumeInput;
  reviewedBy = body.reviewedBy || body.approvedBy || 'developer (unspecified)';
  reviewerNotes = body.notes || body.reviewerNotes || '';
}

const branchName = 'autofix/' + analysis.fixId.toLowerCase();

const prompt = [
  'You are fixing a bug in the repository ' + analysis.repoUrl + ' (base branch: ' + analysis.repoBranch + ').',
  'Bug: ' + analysis.taskName,
  'Root cause: ' + analysis.rootCause,
  'Fix approach: ' + analysis.fixApproach,
  'Affected files: ' + analysis.affectedFiles.join(', '),
  'Test plan: ' + analysis.testPlan,
  'Create a new branch "' + branchName + '" from ' + analysis.repoBranch + ', implement the fix, run "' + analysis.testCommand + '", commit the changes, and report back a diff summary, the list of files changed, and whether the tests passed.'
].join('\n');

return [{
  json: {
    ...analysis,
    reviewedBy,
    reviewerNotes,
    branchName,
    cursorPrompt: prompt
  }
}];

// Parse the Cursor agent's completion payload delivered via the resume webhook,
// validate the test results, and build the GitHub PR + ClickUp update payloads.
const ctx = $('Create Fix Task Payload').first().json;
const resume = $input.first().json;
const result = resume.body || resume;

const testsPassed = result.testsPassed === true || String(result.testsPassed).toLowerCase() === 'true';
const filesChanged = Array.isArray(result.filesChanged) && result.filesChanged.length ? result.filesChanged : ctx.affectedFiles;
const diffSummary = result.diffSummary || result.summary || 'No diff summary provided by the agent.';
const commitSha = result.commitSha || null;
const status = testsPassed ? 'ready_for_review' : 'tests_failed';

const prTitle = '[Auto-fix] ' + ctx.taskName + ' (' + ctx.fixId + ')';
const prBody = [
  '### Root cause',
  ctx.rootCause,
  '',
  '### Fix approach',
  ctx.fixApproach,
  '',
  '### Files changed',
  filesChanged.map(f => '- ' + f).join('\n'),
  '',
  '### Reviewed by',
  ctx.reviewedBy + (ctx.reviewerNotes ? (' — ' + ctx.reviewerNotes) : ''),
  '',
  '### Test results',
  testsPassed ? ('Passed: ' + ctx.testCommand) : ('Failed: ' + ctx.testCommand + ' — needs manual attention.'),
  '',
  diffSummary,
  '',
  '_Generated automatically from ClickUp task ' + ctx.bugId + '._'
].join('\n');

const clickupComment = testsPassed
  ? 'Auto-fix branch "' + ctx.branchName + '" passed tests. Pull request opened for review.'
  : 'Auto-fix branch "' + ctx.branchName + '" was created but tests failed (' + ctx.testCommand + '). PR opened as draft for manual follow-up.';

return [{
  json: {
    ...ctx,
    status,
    testsPassed,
    filesChanged,
    diffSummary,
    commitSha,
    prTitle,
    prBody,
    clickupComment,
    clickupStatus: testsPassed ? 'in review' : 'needs manual fix'
  }
}];
